<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Pipeline_operator_company_model extends CI_Model {
 public function __construct(){parent::__construct();$this->load->model('Pipeline_billing_model','billing');}
 public function row($area){if(!$this->billing->branch_allowed($area))throw new RuntimeException('Area di luar akses Anda.');return $this->db->where('SpbbID',(int)$area)->get('PipelineOperatorCompany')->row_array();}
 /** Validasi identitas dan simpan dengan versi agar perubahan serentak tidak tertimpa. */
 public function save($area,$input,$uploads){$old=$this->row($area);$data=array('SpbbID'=>(int)$area,'UpdatedBy'=>$this->session->userdata('MIS_LOGGED_ID'),'UpdatedAt'=>date('Y-m-d H:i:s'));foreach(array('CompanyName'=>200,'NIB'=>30,'NPWP'=>30,'Address'=>1000,'Phone'=>50,'Email'=>150,'PicName'=>150) as $k=>$max){$v=$input[$k]??'';if(!is_string($v)||mb_strlen($v)>$max)throw new RuntimeException($k.' tidak valid.');$data[$k]=trim($v);}if($data['CompanyName']==='')throw new RuntimeException('Nama perusahaan wajib diisi.');if($data['Email']!==''&&!filter_var($data['Email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Email tidak valid.');
  $paths=array();$this->db->trans_begin();try{$lock=$this->db->query('SELECT SpbbID FROM PipelineOperatorCompany WITH (UPDLOCK,HOLDLOCK) WHERE SpbbID=?',array((int)$area));$current=$this->row($area);if((string)($current['Version']??0)!==(string)($input['Version']??''))throw new RuntimeException('Profil berubah. Muat ulang halaman.');
   foreach(array('Logo','Identity') as $kind){$f=$uploads[$kind]??null;if(!$f||(int)$f['error']===UPLOAD_ERR_NO_FILE)continue;if(!is_scalar($f['error'])||(int)$f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024||!is_uploaded_file($f['tmp_name']))throw new RuntimeException('Upload maksimal 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=array('image/jpeg'=>'jpg','image/png'=>'png');if($kind==='Identity')$allowed['application/pdf']='pdf';if(!isset($allowed[$mime]))throw new RuntimeException($kind==='Logo'?'Logo harus JPG / PNG.':'Identitas harus PDF / JPG / PNG.');if($mime==='application/pdf'){if(file_get_contents($f['tmp_name'],false,null,0,5)!=='%PDF-')throw new RuntimeException('PDF tidak valid.');}else{$size=@getimagesize($f['tmp_name']);if(!$size||$size[0]*$size[1]>16000000)throw new RuntimeException('Gambar maksimal 16 megapiksel.');}
    $dir=APPPATH.'storage/operator_company/';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Penyimpanan belum tersedia.');$stored=bin2hex(random_bytes(24)).'.'.$allowed[$mime];$target=$dir.$stored;if(!move_uploaded_file($f['tmp_name'],$target))throw new RuntimeException('Upload gagal.');$paths[]=$target;$data[$kind.'StoredName']=$stored;$data[$kind.'OriginalName']=mb_substr(basename($f['name']),0,255);$data[$kind.'Mime']=$mime;
   }$data['Version']=(int)($current['Version']??0)+1;$ok=$current?$this->db->where('SpbbID',(int)$area)->update('PipelineOperatorCompany',$data):$this->db->insert('PipelineOperatorCompany',$data);if(!$ok||!$this->db->insert('PipelineDocumentAudit',array('Kind'=>'operator_company','RecordID'=>(int)$area,'Action'=>$current?'EDIT':'CREATE','Snapshot'=>json_encode(array('before'=>$current,'after'=>$data),JSON_UNESCAPED_UNICODE),'UserID'=>$data['UpdatedBy']))||!$this->db->trans_status())throw new RuntimeException('Profil gagal disimpan.');$this->db->trans_commit();return $data;
  }catch(Exception $e){$this->db->trans_rollback();foreach($paths as $path)if(is_file($path))unlink($path);throw $e;}
 }
}
